import React from "react";
import { Card, CardBody } from "reactstrap";

const AIHelper = ({ carbonData }) => {
    const getSuggestion = () => {
        if (carbonData > 100) {
            return "Try using public transport or carpooling to reduce your emissions!";
        } else if (carbonData > 50) {
            return "Consider switching to energy-efficient appliances!";
        } else {
            return "Great job! Keep up the sustainable habits!";
        }
    };

    return (
        <Card className="shadow mt-3">
            <CardBody>
                <h5>AI Suggestion</h5>
                <p>{getSuggestion()}</p>
            </CardBody>
        </Card>
    );
};

export default AIHelper;
